def sha(p):
    h = hashlib.sha256()
    with p.open('rb') as f:
        for chunk in iter(lambda: f.read(1<<20), b''): h.update(chunk)
    return h.hexdigest()

def locate(root, video, hashes):
    candidates = list(root.rglob(video + '.mp4'))
    for p in candidates:
        if sha(p) == hashes: return p
    raise ValueError(f'Cannot find verified video {video} under {root}')

def read_people(r):
    if not len(r.boxes): return []
    if r.keypoints is None or r.keypoints.conf is None: raise ValueError('Missing pose head')
    boxes=r.boxes.xyxy.cpu().tolist(); joints=r.keypoints.data.cpu().tolist()
    if len(boxes)!=len(joints) or any(len(j)!=17 for j in joints): raise ValueError('Unexpected keypoint shape')
    return [{'box':b,'joints':j} for b,j in zip(boxes,joints)]

def main():
    ap=argparse.ArgumentParser(__doc__)
    ap.add_argument('--fp16', type=Path)
    ap.add_argument('--baseline', type=Path,default=Path('models/ncnn_trial_320/yolo11n_pose_320_ncnn_model'))
    ap.add_argument('--videos', type=Path,default=Path('data/raw'))
    ap.add_argument('--output-dir',type=Path,default=Path('outputs')/('fp16_pose_quality_'+datetime.now().strftime('%Y%m%d_%H%M%S')))
    a=ap.parse_args()
    files={v:locate(a.videos,v,s['sha']) for v,s in SPEC['videos'].items()}
    paths=[a.baseline,a.fp16]
    if paths[1] is None:
        for p in Path('.').rglob('model.ncnn.bin'):
            if sha(p)==SPEC['models'][1]['model.ncnn.bin']: paths[1]=p.parent; break
    for p,expected in zip(paths,SPEC['models']):
        if p is None or any(not (p/f).is_file() or sha(p/f)!=h for f,h in expected.items()):
            raise ValueError(f'Cannot verify NCNN model {p}; specify --fp16 or --baseline with original model directory.')
    a.output_dir.mkdir(parents=True,exist_ok=False)
    summary={'status':'incomplete','spec':SPEC,'clips':{}}
    def save():
        tmp=a.output_dir/'summary.tmp'
        tmp.write_text(json.dumps(summary,indent=2),encoding='utf8');tmp.replace(a.output_dir/'summary.json')
    save()
    try:
        os.environ['YOLO_AUTOINSTALL']='false'
        import av,numpy as np
        from ultralytics import YOLO
        models=[YOLO(str(p.resolve()),task='pose') for p in paths]
        for v,p in files.items():
            s=SPEC['videos'][v]; d=[]; n=0; diff=0; multi=0; gate_flip=0; zero=[0,0]
            with av.open(str(p)) as c,(a.output_dir/(v+'.jsonl')).open('x',encoding='utf8') as f:
                for i,frame in enumerate(c.decode(video=0)):
                    if i>=len(s['pts']) or frame.pts!=s['pts'][i] or str(frame.time_base)!=s['time_base']: raise ValueError(f'{v}: PTS mismatch at {i}')
                    img=frame.to_image().convert('RGB')
                    b,h=[read_people(m.predict(img,device='cpu',imgsz=320,batch=1,rect=False,conf=.25,iou=.7,max_det=300,augment=False,save=False,verbose=False)[0]) for m in models]
                    f.write(json.dumps(dict(index=i,pts=frame.pts,baseline=b,fp16=h),allow_nan=False)+'\n')
                    n+=1; diff+=len(b)!=len(h); multi+=max(len(b),len(h))>1
                    zero[0]+=not b;zero[1]+=not h
                    if len(b)==len(h)==1:
                        # Candidate correspondence: exclude unrelated single-person boxes.
                        x,y=np.array([b[0]['box'],h[0]['box']]);inter=np.maximum(0,np.minimum(x[2:],y[2:])-np.maximum(x[:2],y[:2])).prod()
                        union=(x[2:]-x[:2]).prod()+(y[2:]-y[:2]).prod()-inter
                        if union>0 and inter/union>=.5:
                            x,y=np.array([b[0]['joints'],h[0]['joints']]); xb=x[:,2]>=.5;yb=y[:,2]>=.5
                            gate_flip+=int((xb!=yb).sum()); d.extend(np.linalg.norm((x-y)[xb&yb,:2],axis=1).tolist())
            if n!=len(s['pts']):raise ValueError(f'{v}: truncated')
            summary['clips'][v]=dict(frames=n,count_disagreement=diff,zero_person_baseline_fp16=zero,multiple_either=multi,joint_gate_flips_on_matched_singletons=gate_flip,comparable_joints=len(d),pixel_median_p95_max=np.percentile(d,[50,95,100]).tolist() if d else None);save()
            print(v,summary['clips'][v],flush=True)
        summary['status']='complete';save()
    except BaseException as e:
        summary['error']=repr(e);save();raise
    print(a.output_dir.resolve())
if __name__=='__main__': main()
